import unittest

def can_commit_removal_fixed(acks, old_voters, new_voters):
    acknowledgements = set(acks)
    old_majority = len(old_voters) // 2 + 1
    new_majority = len(new_voters) // 2 + 1
    return (len(acknowledgements & old_voters) >= old_majority
            and len(acknowledgements & new_voters) >= new_majority)

class RemovalQuorumTests(unittest.TestCase):
    def test_new_configuration_cannot_authorize_its_own_activation(self):
        old_voters = {'a', 'b', 'c', 'd', 'e'}
        new_voters = {'a', 'b', 'c'}
        acknowledgements = {'a', 'b'}
        self.assertTrue(can_commit_removal(acknowledgements, old_voters, new_voters))
        self.assertFalse(can_commit_removal_fixed(acknowledgements, old_voters, new_voters))

    def test_both_configurations_can_authorize_transition(self):
        old_voters = {'a', 'b', 'c', 'd', 'e'}
        new_voters = {'a', 'b', 'c'}
        acknowledgements = {'a', 'b', 'c'}
        self.assertTrue(can_commit_removal_fixed(acknowledgements, old_voters, new_voters))
